"tags": [],
"notes": "Не больше 2 порций в одной сковороде. На 4 порции — два захода. Мерить соус точно: он сбалансирован на вес лапши.",
"tips": [
[
"Почему могло не получаться",
"Почему дома не выходило — почти наверняка одно из этого: (1) лапшу варили, а её надо замачивать в воде комнатной температуры около часа — варёная в воке превращается в кашу; (2) соус без тамаринда (на кетчупе/лайме/соевом) — тамаринд и есть вкус пад тая; (3) жарили больше 2 порций за раз — лапша тушится, а не жарится; (4) мало огня и мало масла — слипается. Плюс сладкая маринованная редька и сушёные креветки дают тот самый «уличный» вкус."
],
[
"Замены",
"Нельзя менять: тамаринд (паста тамаринда есть на Ozon), рыбный соус, рисовая лапша. Можно: пальмовый сахар → тростниковый; чесночный лук → зелёный (рубить мельче); сушёные креветки и редьку — пропустить, будет чуть менее «уличный», но всё ещё пад тай."
]
],
