"notes": "Почему его не любят: в столовой его тушили из жёсткого мяса час под мукой — выходила серая подошва. Здесь мясо сочное и розовое внутри, а соус — горчично-сметанный, лёгкий. Если всё-таки хочется взять дешёвую лопатку — тогда тушить в соусе час под крышкой со 300 мл бульона (это уже другой, «домашний» бефстроганов).",
